// Session 5 — a tiny shop API with switchable test conditions.
//
//   node server.mjs            then open http://localhost:5050
//   PORT=6000 node server.mjs  to use another port
//
// No dependencies: only Node's built-in modules (Node 18 or newer).
// Do not edit this file — the exercise is about the code in public/versions/.

import http from 'node:http';
import { readFile } from 'node:fs/promises';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const PORT = Number(process.env.PORT) || 5050;
const PUBLIC_DIR = path.join(path.dirname(fileURLToPath(import.meta.url)), 'public');

// The catalogue from session 4. One name contains text that LOOKS like HTML:
// it must appear on the page exactly as written, tags and all.
const PRODUCTS = [
  { id: 'tshirt', name: 'T-shirt', price: 180000 },
  { id: 'hoodie', name: 'Hoodie', price: 420000 },
  { id: 'somi', name: 'Áo sơ mi tay dài kẻ sọc xanh navy', price: 350000 },
  { id: 'cap', name: 'Cap', price: 95000 },
  { id: 'tote', name: 'Tote bag', price: 120000 },
  { id: 'socks', name: 'Socks, 3 pairs', price: 75000 },
  { id: 'jacket', name: 'Jacket', price: 890000 },
  { id: 'scarf', name: 'Scarf <i>limited</i>', price: 160000 },
];

// Units in the warehouse, served one product at a time by /api/stock/:id.
const STOCK = { tshirt: 12, hoodie: 5, somi: 3, cap: 20, tote: 0, socks: 30, jacket: 2, scarf: 7 };

// Test condition for GET /api/products. Change it with POST /__mode
// (the "Test conditions" panel on the page does that for you).
const MODES = {
  normal: 'answer at once with 8 products',
  slow: 'answer after 3 seconds',
  error: 'answer HTTP 500 with a JSON error',
  hang: 'send nothing for 30 seconds, then HTTP 504',
  empty: 'answer at once with []',
};
let mode = 'normal';

const TYPES = {
  '.html': 'text/html; charset=utf-8',
  '.css': 'text/css; charset=utf-8',
  '.js': 'text/javascript; charset=utf-8',
  '.mjs': 'text/javascript; charset=utf-8',
  '.json': 'application/json; charset=utf-8',
  '.svg': 'image/svg+xml',
  '.png': 'image/png',
  '.ico': 'image/x-icon',
};

function sendJson(res, status, body) {
  if (res.writableEnded || res.destroyed) return;
  res.writeHead(status, { 'Content-Type': 'application/json; charset=utf-8', 'Cache-Control': 'no-store' });
  res.end(JSON.stringify(body));
}

// Run `fn` after `ms`, unless the browser gives up on the request first.
function later(res, ms, fn) {
  const timer = setTimeout(fn, ms);
  res.on('close', () => clearTimeout(timer));
}

function escapeHtml(s) {
  return String(s)
    .replaceAll('&', '&amp;').replaceAll('<', '&lt;').replaceAll('>', '&gt;')
    .replaceAll('"', '&quot;').replaceAll("'", '&#39;');
}

const vnd = (n) => n.toLocaleString('vi-VN') + ' đ';

// GET /ssr — the same catalogue, but the SERVER builds the HTML. The browser
// receives finished markup: no fetch, no template, no JavaScript needed.
function renderSsrPage() {
  const total = PRODUCTS.reduce((sum, p) => sum + p.price * STOCK[p.id], 0);
  const cards = PRODUCTS.map((p) => `
      <li class="card" data-id="${escapeHtml(p.id)}">
        <h2 class="name">${escapeHtml(p.name)}</h2>
        <p class="price">${vnd(p.price)}</p>
      </li>`).join('');
  return `<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <title>Catalogue — server-rendered</title>
  <link rel="stylesheet" href="/style.css">
</head>
<body>
  <header class="toolbar">
    <a class="brand" href="/">Shop</a>
    <p class="menu">Rendered on the server · <a href="/">back to the browser-rendered page</a></p>
  </header>
  <main class="page">
    <h1 class="title">Catalogue (server-rendered)</h1>
    <p class="stock-total">Stock value: <output id="stock-value">${vnd(total)}</output></p>
    <p class="status" id="status" role="status"></p>
    <ul class="catalogue" id="catalogue">${cards}
    </ul>
  </main>
  <footer class="footer">CSC13008 · Session 5 · This HTML was built by server.mjs at ${new Date().toISOString()}.</footer>
</body>
</html>
`;
}

async function serveStatic(res, pathname) {
  const rel = pathname === '/' ? 'index.html' : decodeURIComponent(pathname).replace(/^\/+/, '');
  const file = path.join(PUBLIC_DIR, rel);
  if (!file.startsWith(PUBLIC_DIR + path.sep)) return sendJson(res, 403, { error: 'Forbidden' });
  try {
    const body = await readFile(file);
    res.writeHead(200, {
      'Content-Type': TYPES[path.extname(file)] || 'application/octet-stream',
      'Cache-Control': 'no-cache',
    });
    res.end(body);
  } catch {
    sendJson(res, 404, { error: `Not found: ${pathname}` });
  }
}

function readBody(req) {
  return new Promise((resolve, reject) => {
    let data = '';
    req.setEncoding('utf8');
    req.on('data', (chunk) => {
      data += chunk;
      if (data.length > 10_000) reject(new Error('Body too large'));
    });
    req.on('end', () => resolve(data));
    req.on('error', reject);
  });
}

const server = http.createServer(async (req, res) => {
  const { pathname } = new URL(req.url, 'http://localhost');
  const started = Date.now();
  const modeNow = mode; // the test condition this request arrived under
  const log = (outcome) => console.log(
    `${new Date().toISOString().slice(11, 19)}  ${req.method} ${req.url}  [mode=${modeNow}]  -> ${outcome}`);
  res.on('finish', () => log(`${res.statusCode}  ${Date.now() - started} ms`));
  res.on('close', () => {
    if (!res.writableEnded) log(`no answer: the browser gave up after ${Date.now() - started} ms`);
  });

  try {
    if (pathname === '/__mode') {
      if (req.method === 'GET') return sendJson(res, 200, { mode, modes: MODES });
      if (req.method === 'POST') {
        let wanted;
        try { wanted = JSON.parse(await readBody(req)).mode; } catch { wanted = undefined; }
        if (!Object.hasOwn(MODES, wanted)) {
          return sendJson(res, 400, { error: `mode must be one of: ${Object.keys(MODES).join(', ')}` });
        }
        mode = wanted;
        console.log(`---- test condition is now "${mode}": GET /api/products will ${MODES[mode]}`);
        return sendJson(res, 200, { mode });
      }
      return sendJson(res, 405, { error: 'Use GET or POST' });
    }

    if (req.method === 'GET' && pathname === '/api/products') {
      if (mode === 'normal') return sendJson(res, 200, PRODUCTS);
      if (mode === 'empty') return sendJson(res, 200, []);
      if (mode === 'slow') return later(res, 3000, () => sendJson(res, 200, PRODUCTS));
      if (mode === 'error') return sendJson(res, 500, { error: 'Database unavailable (test condition "error")' });
      if (mode === 'hang') {
        return later(res, 30_000, () => sendJson(res, 504, { error: 'Upstream timed out after 30 s (test condition "hang")' }));
      }
    }

    const stockMatch = pathname.match(/^\/api\/stock\/([^/]+)$/);
    if (req.method === 'GET' && stockMatch) {
      const id = decodeURIComponent(stockMatch[1]);
      const delay = 100 + Math.floor(Math.random() * 501); // 100–600 ms
      return later(res, delay, () => {
        if (!Object.hasOwn(STOCK, id)) return sendJson(res, 404, { error: `Unknown product id: ${id}` });
        sendJson(res, 200, { id, stock: STOCK[id] });
      });
    }

    if (pathname.startsWith('/api/')) return sendJson(res, 404, { error: `No such endpoint: ${req.method} ${pathname}` });

    if (req.method === 'GET' && pathname === '/ssr') {
      res.writeHead(200, { 'Content-Type': 'text/html; charset=utf-8', 'Cache-Control': 'no-store' });
      return res.end(renderSsrPage());
    }

    if (req.method === 'GET') return serveStatic(res, pathname);
    sendJson(res, 405, { error: 'Method not allowed' });
  } catch (err) {
    console.error(err);
    sendJson(res, 500, { error: 'Server bug — see the terminal' });
  }
});

server.listen(PORT, () => {
  console.log(`Session 5 shop on http://localhost:${PORT}  (server-rendered copy: http://localhost:${PORT}/ssr)`);
  console.log(`Test condition: "${mode}". Press Ctrl+C to stop.`);
});
